//! Replays the pre-commit 4.7.0 oracle vectors (`tests/vectors/*.json`, generated by
//! `tests/oracle/gen_config_vectors.py` on CPython 3.12.3): every config/manifest fixture's warnings (in order)
//! and `str(InvalidConfigError)` byte for byte in both brands and both extension modes, the merge (`_hook` +
//! `Hook.create`), migrate-config and the autoupdate rev rewrite. Registered divergences carry their snp
//! expectation in the vector.
//!
//! Owner: WP-21.

#[cfg(test)]
pub mod support;

#[cfg(test)]
mod vectors {
    use std::ffi::OsStr;

    use serde_json::Value as Json;
    use snp_config::migrate::{Outcome, migrate_config};
    use snp_config::revline::{RevUpdate, Rewrite, rewrite};
    use snp_config::{ConfigSource, ExtMode, HookDef, RepoConfig, finalize_local, merge_hook};
    use snp_core::output::CollectWarnings;

    use crate::support::{BRANDS, brand_text, file_in_tempdir, vectors, with_opts};

    fn input(c: &Json) -> Option<Vec<u8>> {
        if c.get("missing").is_some() {
            return None;
        }
        if let Some(s) = c["input"].as_str() {
            return Some(s.as_bytes().to_vec());
        }
        let hex = c["input_hex"].as_str().map_or_default(str::as_bytes);
        let digit = |b: u8| char::from(b).to_digit(16).unwrap_or(0);
        Some(
            hex.as_chunks::<2>()
                .0
                .iter()
                .map(|[hi, lo]| u8::try_from(digit(*hi) * 16 + digit(*lo)).unwrap_or(0))
                .collect(),
        )
    }

    fn strs(v: &Json) -> Vec<String> {
        v.as_array().map_or_default(|a| {
            a.iter()
                .map(|s| s.as_str().expect("str").to_owned())
                .collect()
        })
    }

    #[test]
    fn load_vectors_match_pre_commit() {
        let cases = vectors("load.json");
        assert!(cases.len() >= 200, "{} cases", cases.len());
        let mut failures = Vec::new();
        for c in &cases {
            let name = c["name"].as_str().expect("name");
            let kind = c["kind"].as_str().expect("kind");
            let file = c["file"].as_str().expect("file");
            let bytes = input(c);
            let mut modes = vec![ExtMode::Strict];
            if c.get("ext").is_none() {
                modes.push(ExtMode::Enabled);
            }
            let divergent = c.get("divergence").is_some();
            let want_warnings = if divergent && c.get("snp_warnings").is_some() {
                strs(&c["snp_warnings"])
            } else {
                strs(&c["warnings"])
            };
            let want_error = if divergent {
                c["snp_error"].as_str().map(str::to_owned)
            } else {
                c["error"].as_str().map(str::to_owned)
            };
            if !divergent && !c["exc"].is_null() {
                failures.push(format!(
                    "{name}: an undeclared pre-commit crash {}",
                    c["exc"]
                ));
                continue;
            }
            for brand in BRANDS {
                for &ext in &modes {
                    let (dir, path) = file_in_tempdir(file, bytes.as_deref());
                    let loaded = with_opts(brand, ext, |o| {
                        if kind == "config" {
                            let src = ConfigSource {
                                path: path.clone(),
                                display: file.into(),
                                project_root: dir.path().to_path_buf(),
                            };
                            snp_config::load_config(&src, o).map(|_| ())
                        } else {
                            snp_config::load_manifest(&path, OsStr::new(file), o).map(|_| ())
                        }
                    });
                    let tag = format!("{name} [{brand:?}, {ext:?}]");
                    let want_w: Vec<String> =
                        want_warnings.iter().map(|w| brand_text(brand, w)).collect();
                    if loaded.warnings != want_w {
                        failures.push(format!(
                            "{tag}: warnings\n  got  {:?}\n  want {want_w:?}",
                            loaded.warnings
                        ));
                    }
                    let got_error = loaded.result.as_ref().err().map(|e| e.rendered.clone());
                    let want_e = want_error.as_deref().map(|e| brand_text(brand, e));
                    if got_error != want_e {
                        failures.push(format!(
                            "{tag}: error\n  got  {got_error:?}\n  want {want_e:?}"
                        ));
                    }
                    if let Err(e) = &loaded.result {
                        let want_manifest = kind == "manifest";
                        if e.manifest != want_manifest && e.uncaught().is_none() {
                            failures.push(format!("{tag}: manifest flag {}", e.manifest));
                        }
                    }
                    {
                        let mut want_fw: Vec<String> = Vec::new();
                        let fw = if divergent && c.get("snp_future_warnings").is_some() {
                            &c["snp_future_warnings"]
                        } else {
                            &c["future_warnings"]
                        };
                        for m in strs(fw) {
                            if !want_fw.contains(&m) {
                                want_fw.push(m);
                            }
                        }
                        let got_fw: Vec<String> = loaded
                            .diag
                            .iter()
                            .map(|l| {
                                l.rsplit_once(": ")
                                    .and_then(|(_, m)| m.strip_suffix(" (Python FutureWarning)"))
                                    .unwrap_or(l)
                                    .to_owned()
                            })
                            .collect();
                        let mut got_dedup: Vec<String> = Vec::new();
                        for m in got_fw {
                            if !got_dedup.contains(&m) {
                                got_dedup.push(m);
                            }
                        }
                        if got_dedup != want_fw {
                            failures.push(format!(
                                "{tag}: future warnings {:?} want {want_fw:?}",
                                loaded.diag
                            ));
                        }
                    }
                }
            }
        }
        assert!(
            failures.is_empty(),
            "{} failures:\n{}",
            failures.len(),
            failures.join("\n")
        );
    }

    /// `Hook` fields of the oracle (names sorted) as the test compares them.
    fn hook_json(h: &HookDef) -> Json {
        let list = |xs: &[std::sync::Arc<str>]| {
            Json::from(xs.iter().map(ToString::to_string).collect::<Vec<_>>())
        };
        let tags = |t: &file_identify::TagSet| {
            let mut v: Vec<String> = t.names().map(str::to_owned).collect();
            v.sort();
            Json::from(v)
        };
        let mut stages: Vec<String> = h.stages.iter().map(|s| s.as_str().to_owned()).collect();
        stages.sort();
        serde_json::json!({
            "id": &*h.id, "name": &*h.name, "entry": &*h.entry, "language": h.language.as_str(), "alias": &*h.alias,
            "files": &*h.files, "exclude": &*h.exclude, "types": tags(&h.types), "types_or": tags(&h.types_or),
            "exclude_types": tags(&h.exclude_types), "additional_dependencies": list(&h.additional_dependencies),
            "args": list(&h.args), "always_run": h.always_run, "fail_fast": h.fail_fast,
            "pass_filenames": h.pass_filenames, "description": &*h.description,
            "language_version": &*h.language_version, "log_file": &*h.log_file,
            "minimum_pre_commit_version": &*h.minimum_pre_commit_version, "require_serial": h.require_serial,
            "stages": stages, "verbose": h.verbose,
        })
    }

    /// The oracle's hook in the test's form. A meta hook's `entry` is `{sys.executable} -m
    /// pre_commit.meta_hooks.<module>` in pre-commit and snp's internal sentinel (meta hooks run in-process,
    /// ARCHITECTURE §3.11); it never reaches a shell, so it is compared by module only.
    fn oracle_hook(h: &Json) -> Json {
        let mut h = h.clone();
        if let Some(e) = h["entry"].as_str()
            && let Some((_, module)) = e.split_once(" -m pre_commit.meta_hooks.")
        {
            h["entry"] = Json::from(format!("snp -m pre_commit.meta_hooks.{module}"));
        }
        for k in ["types", "types_or", "exclude_types", "stages"] {
            let mut v = strs(&h[k]);
            v.sort();
            v.dedup();
            h[k] = Json::from(v);
        }
        h
    }

    #[test]
    fn merge_vectors_match_pre_commit() {
        let cases = vectors("merge.json");
        assert!(cases.len() >= 10);
        for c in &cases {
            let name = c["name"].as_str().expect("name");
            for brand in BRANDS {
                let config = crate::support::load_config_text(
                    c["config"].as_str().expect("config"),
                    brand,
                    ExtMode::Enabled,
                );
                let (cfg, _) = crate::support::ok(config);
                let manifest = c["manifest"]
                    .as_str()
                    .map(|m| crate::support::ok(crate::support::load_manifest_text(m, brand)).0);
                let warn = CollectWarnings::new();
                let mut logs: Vec<Json> = Vec::new();
                let mut hooks: Vec<Json> = Vec::new();
                let mut exit = Json::Null;
                // pre-commit's order: a local/meta hook is merged and created (W11) one at a time; a cloned repo
                // runs `_hook` for all its hooks before any `Hook.create`, so its W11s are buffered per repo and
                // dropped on an error (`merge_hook`'s "Warning order").
                let mut fail = |logs: &mut Vec<Json>, e: &snp_config::MergeError| {
                    logs.push(serde_json::json!(["ERROR", e.message(brand)]));
                    exit = Json::from(1);
                };
                'repos: for repo in &cfg.repos {
                    match repo {
                        RepoConfig::Local { hooks: local } | RepoConfig::Meta { hooks: local } => {
                            let src = if matches!(repo, RepoConfig::Local { .. }) {
                                "local"
                            } else {
                                "meta"
                            };
                            for h in local {
                                let b = finalize_local(h, &cfg, src, None, &warn);
                                for w in warn.take() {
                                    logs.push(serde_json::json!(["WARNING", w]));
                                }
                                match b {
                                    Ok(h) => hooks.push(hook_json(&h)),
                                    Err(e) => {
                                        fail(&mut logs, &e);
                                        break 'repos;
                                    }
                                }
                            }
                        }
                        RepoConfig::Remote {
                            repo,
                            hooks: remote,
                            ..
                        } => {
                            let m = manifest.as_ref().expect("manifest");
                            if let Some(missing) = remote.iter().find(|h| m.get(&h.id).is_none()) {
                                let e = snp_config::MergeError::UnknownId {
                                    id: std::sync::Arc::clone(&missing.id),
                                    repo: std::sync::Arc::clone(repo),
                                };
                                fail(&mut logs, &e);
                                break 'repos;
                            }
                            let buffer = CollectWarnings::new();
                            let mut merged = Vec::new();
                            for h in remote {
                                let m = m.get(&h.id).expect("hook");
                                match merge_hook(m, h, &cfg, repo, None, &buffer) {
                                    Ok(h) => merged.push(h),
                                    Err(e) => {
                                        fail(&mut logs, &e);
                                        break 'repos;
                                    }
                                }
                            }
                            for w in buffer.take() {
                                logs.push(serde_json::json!(["WARNING", w]));
                            }
                            hooks.extend(merged.iter().map(hook_json));
                        }
                        _ => {}
                    }
                }
                let want_logs: Vec<Json> = c["logs"]
                    .as_array()
                    .expect("logs")
                    .iter()
                    .map(|l| {
                        serde_json::json!([l[0], brand_text(brand, l[1].as_str().expect("msg"))])
                    })
                    .collect();
                assert_eq!(logs, want_logs, "{name} [{brand:?}] logs");
                assert_eq!(exit, c["exit"], "{name} [{brand:?}] exit");
                let want_hooks: Vec<Json> = c["hooks"]
                    .as_array()
                    .expect("hooks")
                    .iter()
                    .map(oracle_hook)
                    .collect();
                assert_eq!(hooks, want_hooks, "{name} [{brand:?}] hooks");
            }
        }
    }

    #[test]
    fn migrate_vectors_match_pre_commit() {
        let cases = vectors("migrate.json");
        assert!(cases.len() >= 20);
        for c in &cases {
            let name = c["name"].as_str().expect("name");
            let input = c["input"].as_str().expect("input");
            let got = migrate_config(input.as_bytes(), OsStr::new(".pre-commit-config.yaml"));
            match (&got, c["error"].as_str(), c["exc"].as_str()) {
                (Err(e), Some(want), _) => assert_eq!(e.rendered, want, "{name}"),
                (Err(e), None, Some(exc)) => {
                    assert_eq!(c["divergence"], "D-CRASH-07", "{name}");
                    let (_, msg) = exc.split_once(": ").expect("exc");
                    assert_eq!(
                        e.rendered,
                        format!("\n==> File .pre-commit-config.yaml\n=====> {msg}"),
                        "{name}"
                    );
                }
                (Ok(out), None, None) => {
                    let want = c["snp_output"]
                        .as_str()
                        .or_else(|| c["output"].as_str())
                        .expect("output");
                    let stdout = c["stdout"].as_str().expect("stdout");
                    match out {
                        Outcome::Migrated(b) => {
                            assert_eq!(stdout, "Configuration has been migrated.\n", "{name}");
                            assert_eq!(std::str::from_utf8(b).expect("utf8"), want, "{name}");
                        }
                        Outcome::AlreadyMigrated => {
                            assert_eq!(stdout, "Configuration is already migrated.\n", "{name}");
                            assert_eq!(input, want, "{name}");
                        }
                        _ => panic!("{name}: unknown outcome"),
                    }
                }
                (got, _, _) => panic!("{name}: got {got:?}, want {c}"),
            }
        }
    }

    #[test]
    fn revline_vectors_match_pre_commit() {
        let cases = vectors("revline.json");
        assert!(cases.len() >= 15);
        for c in &cases {
            let name = c["name"].as_str().expect("name");
            let updates: Vec<RevUpdate> = c["updates"]
                .as_array()
                .expect("updates")
                .iter()
                .map(|u| RevUpdate {
                    repo_index: usize::try_from(u["repo_index"].as_u64().expect("idx"))
                        .expect("usize"),
                    new_rev: u["rev"].as_str().expect("rev").into(),
                    frozen_comment: u["frozen"].as_str().map(Into::into),
                })
                .collect();
            let got =
                rewrite(c["input"].as_str().expect("input").as_bytes(), &updates).expect(name);
            let want = c["snp_output"]
                .as_str()
                .or_else(|| c["output"].as_str())
                .expect("output");
            let want_reformat = c
                .get("snp_reformatted")
                .and_then(Json::as_bool)
                .unwrap_or_else(|| c["reformatted"].as_bool().expect("reformatted"));
            let (bytes, reformatted) = match got {
                Rewrite::Lines(b) => (b, false),
                Rewrite::FullReformat(b) => (b, true),
                _ => panic!("{name}"),
            };
            assert_eq!(std::str::from_utf8(&bytes).expect("utf8"), want, "{name}");
            assert_eq!(reformatted, want_reformat, "{name}");
        }
    }
}
